css:
.t{background:#0c1630;font-family:Poppins,Arial,sans-serif;color:#fff}
.bm{position:absolute;width:769.86px;height:1564.53px;transform:rotate(-150.17deg);background:linear-gradient(180deg,rgba(0,64,223,0) 8.655%,#0040df 79.991%);opacity:.072}
.bm1{left:581.5px;top:-542.7px}.bm2{left:633.2px;top:-512.8px}.bm3{left:685px;top:-482.9px}.bm4{left:736.7px;top:-453.1px}
.bm5{left:788.4px;top:-423.2px}.bm6{left:840.1px;top:-393.3px}.bm7{left:891.9px;top:-363.5px}.bm8{left:943.6px;top:-333.6px}
.bm9{left:995.3px;top:-303.7px}.bm10{left:1048px;top:-273.3px}.bm11{left:1100.7px;top:-242.9px}.bm12{left:1148.2px;top:-236.2px}.bm13{left:1155.8px;top:-155.6px}
.shade{position:absolute;inset:0;background:linear-gradient(238.4deg,rgba(0,9,32,0) 30.4%,#000920 97.8%)}
.pill{position:absolute;left:-33px;top:118px;height:66.76px;border-radius:33.4px;background:#fff;display:flex;align-items:center;padding:0 46px 0 101px}
.lk{display:flex;flex-direction:column;align-items:flex-end;width:154px;flex:none;margin-top:4px}
.lk img{width:154px;height:auto}
.lk span{font:700 10.6px/1 Poppins;letter-spacing:.35px;color:#1b2440;margin-top:4.5px}
.pill .dv{width:1px;height:42px;background:#a3abbd;margin:0 17px 0 20px;flex:none}
.pill .pl{max-width:120px;height:48px;object-fit:contain;object-position:center}
.copy{position:absolute;left:68px;top:214px;width:462px;height:310px;display:flex;flex-direction:column;justify-content:center;align-items:flex-start}
.copy>*{flex:none}
.title{width:453px;max-height:148px;padding-bottom:11px;margin-bottom:-11px;overflow:hidden;font:600 62.34px/1.095 Poppins;letter-spacing:-.2px;color:#fff}
.title .hl{color:#ffe500}
.sub{margin-top:8px;width:453px;max-height:76px;padding-bottom:4px;margin-bottom:-4px;overflow:hidden;font:italic 400 27.8px/1.275 Poppins;color:#fff}
.chip{margin-top:26px;height:38.67px;display:flex;align-items:center;gap:6.5px;padding:0 14px;border-radius:9.65px;background:rgba(0,64,223,.19);font:500 20.13px/1 Poppins;color:#fff;white-space:nowrap}
.chip svg{width:22.6px;height:22.3px;flex:none}
.cta{margin-top:18px;height:46px;display:flex;align-items:center;gap:10px;padding:0 22px;border-radius:10px;background:#ffe500;font:600 18px/1 Poppins;color:#0c1630;white-space:nowrap}
.cta svg{width:11px;height:12px}
.row{position:absolute;left:530px;top:86px;width:630px;height:430px;display:flex;justify-content:center;align-items:flex-start}
.c3{gap:0}.c3 .sp+.sp{margin-left:-24px}
.c2{gap:36px}
.c1 .sp{transform:scale(1.2);transform-origin:50% 40%}
.sp{position:relative;width:219px;height:426px;flex:none}
.fr{position:absolute;left:35px;top:89.4px;width:150px;height:191.3px;border-radius:16px;transform:skewX(-14.67deg);background:linear-gradient(205deg,#2a5cff 0%,#1447f2 45%,#0a39d0 100%)}
.ph{position:absolute;left:46px;top:5px;width:130px;height:276px;border-radius:0 0 16px 16px;overflow:hidden;transform:skewX(-14.67deg)}
.ph img{position:absolute;left:-36px;top:0;width:202px;height:276px;max-width:none;object-fit:cover;object-position:center top;transform:skewX(14.67deg)}
.ini{position:absolute;left:35px;top:89.4px;width:150px;height:191.3px;display:flex;align-items:center;justify-content:center;font:600 54px/1 Poppins;color:rgba(255,255,255,.92)}
.tx{position:absolute;left:-25px;top:312px;width:200px;text-align:center}
.tx .n{height:24px;font:500 20.63px/24px Poppins;color:#fff;white-space:nowrap;overflow:hidden}
.tx .d{margin:0 auto;width:182px;max-height:34px;overflow:hidden;font:400 12.78px/17.02px Poppins;color:#9ebafe}
.tile{position:absolute;left:-25px;top:380.5px;width:200px;display:flex;justify-content:center}
.tile div{height:44.9px;min-width:100px;max-width:200px;padding:0 18px;border-radius:8px;background:#fff;display:flex;align-items:center;justify-content:center}
.tile img{height:30px;max-width:150px;object-fit:contain}
.tile b{font:700 15px/1 Poppins;color:#0c1630;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:164px}
